import {REPORT_CYCLES,EFFORT_GRADES,ATTAINMENT_GRADES} from './report-config.mjs';
export function createReportsUI(ui){
 const {esc,button,options,empty}=ui,$=s=>document.querySelector(s),books=new Map(),lists=new Map(),bundles=new Map();let config=null,editor=null,homeroomEditor=null,busy=false,pending=null,filterText='',filterStatus='all';
 async function api(path,opts={}){const response=await fetch('/api/report-cards'+path,{credentials:'same-origin',cache:'no-store',...opts,headers:{'Content-Type':'application/json',...opts.headers}}),data=await response.json();if(!response.ok)throw Error(data.error||'Could not load reports.');return data;}
 function isReviewer(){return ui.teacher()?.role==='report-reviewer';}
 function context(){const params=ui.route().params,cycleId=REPORT_CYCLES.some(c=>c.id===params.get('cycle'))?params.get('cycle'):'october-2026',selected=config?.classes.find(c=>c.id===params.get('class'))||(!isReviewer()&&params.get('view')!=='students'&&!params.get('student')?config?.classes[0]:null);return{cycleId,classId:selected?.id||'',subject:params.get('subject')||'',studentId:params.get('student')||''};}
 function invalidate(){books.clear();lists.clear();bundles.clear();editor=null;homeroomEditor=null;ui.setDirty(false);}
 function load(map,key,path){if(map.has(key))return;map.set(key,{loading:true});api(path).then(data=>map.set(key,data)).catch(error=>map.set(key,{error:error.message})).finally(()=>{if(['/cards','/home'].includes(ui.route().path)&&ui.canRender())ui.render();});}
 function guard(fn){if(!ui.isDirty()){fn();return;}pending=fn;ui.openDialog('Keep your report changes?','<p>Your current report changes have not been saved.</p>',button('Keep editing','close')+button('Discard changes','report-discard','','danger'));}
 function page(params){if(!config){config={loading:true};api('/config').then(data=>config=data).catch(error=>config={error:error.message}).finally(()=>{if(ui.canRender())ui.render();});}if(config.loading)return empty('Loading report workspace','');if(config.error)return '<div class="error">'+esc(config.error)+'</div>';const ctx=context(),cycle=REPORT_CYCLES.find(c=>c.id===ctx.cycleId);if(ctx.studentId)return studentPage(ctx);const listView=isReviewer()||params.get('view')==='students';
 const head=`<div class="report-workspace-head"><div><h1>${isReviewer()?'Report review':'Report cards'}</h1><p>${esc(cycle.academicYear)} · ${esc(cycle.title)} · ${isReviewer()?'Review submitted work, then issue a whole-student report.':'Enter effort and attainment, then submit for review.'}</p></div><label class="field"><span>Reporting cycle</span><select id="reporting-cycle">${options(config.cycles.map(c=>[c.id,c.label]),ctx.cycleId)}</select></label></div><div class="report-workspace-tools">${!isReviewer()?`<div class="grade-mode">${button('Enter class reports','report-mode','data-mode="entry"',!listView?'primary small':'small')}${button('Whole-student reports','report-mode','data-mode="students"',listView?'primary small':'small')}</div>`:'<span class="badge">Reviewer account · decisions are recorded</span>'}<label class="field grow"><span>Class</span><select id="reporting-class">${options([...(listView?[['',isReviewer()?'All students':'All my students']]:[]),...config.classes.map(c=>[c.id,c.name])],ctx.classId)}</select></label></div><div id="page-error" class="error" role="alert"></div>`;
 return head+(listView?studentList(ctx):classEntry(ctx));}
 function classEntry(ctx){if(!ctx.classId)return empty('Choose a class','');const key=ctx.cycleId+'|'+ctx.classId+'|'+ctx.subject;load(books,key,'/class?'+new URLSearchParams(ctx));const book=books.get(key);if(book.loading)return empty('Loading shared class reports','');if(book.error)return '<div class="error">'+esc(book.error)+'</div>';if(!editor||editor.key!==key)editor={key,rows:structuredClone(book.rows),dirty:false};if(editor.dirty)ui.setDirty(true);const draftRows=editor.rows.filter(r=>r.status==='draft');return `${book.subjects.length>1?`<label class="field report-subject-field"><span>Subject</span><select id="reporting-subject">${options(book.subjects.map(s=>[s,s]),book.subject)}</select></label>`:''}<section class="panel report-entry-panel"><div class="panel-head"><div><h2>${esc(book.subject)}</h2><p>${draftRows.length} editable · ${editor.rows.filter(r=>r.status==='pending').length} submitted · ${editor.rows.filter(r=>r.status==='approved').length} approved. Assessment means are context, not automatic report grades.</p></div>${button('Class draft PDFs','report-download','data-scope="class"','small')}</div><div class="table-wrap"><table class="data-table report-entry-table"><thead><tr><th>Student</th><th>Assessment mean</th><th>Attainment</th><th>Effort</th><th>Note</th><th>Status / action</th></tr></thead><tbody>${editor.rows.map(r=>{const s=ui.student(r.studentId),locked=r.status!=='draft';return `<tr><td><a href="#/cards?${new URLSearchParams({student:r.studentId,cycle:ctx.cycleId})}">${esc(s.name)}</a></td><td>${r.assessmentMean===null?'—':Math.round(r.assessmentMean*10)/10+'%'}<small>${r.assessmentsMarked} marked assessments</small></td><td><select data-report-field="grade" data-row="${esc(r.id)}" aria-label="Attainment for ${esc(s.name)}" ${locked?'disabled':''}>${options([['','Grade'],...ATTAINMENT_GRADES.map(g=>[g,g])],r.grade)}</select></td><td><select data-report-field="effort" data-row="${esc(r.id)}" aria-label="Effort for ${esc(s.name)}" ${locked?'disabled':''}>${options([['','Effort'],...EFFORT_GRADES.map(([code,label])=>[code,code+' · '+label])],r.effort)}</select></td><td>${button(r.comment?'Edit':'Add','report-comment',`data-id="${esc(r.id)}" ${locked?'disabled':''}`,'small')}</td><td><span class="badge ${r.status}">${{draft:'Draft',pending:'Submitted',approved:'Approved'}[r.status]}</span>${r.status==='draft'?button('Submit','report-submit-row',`data-id="${esc(r.id)}"`,'small'):''}${r.reviewNote?button('Feedback','report-feedback',`data-id="${esc(r.id)}" title="${esc(r.reviewNote)}"`,'small'):''}</td></tr>`;}).join('')}</tbody></table></div></section><div class="save-bar"><span id="save-status">${editor.dirty?'Unsaved report changes':'Shared report records · '+editor.rows.length+' students'}</span><div class="actions">${button('Save drafts','report-save','','')}${button('Submit completed rows','report-submit','','primary')}</div></div>`;}
 function studentList(ctx){const selected=ui.route().params.get('class')||'',key=ctx.cycleId+'|'+selected;load(lists,key,'/students?'+new URLSearchParams({cycleId:ctx.cycleId,classId:selected,activity:String(isReviewer()||ctx.cycleId.startsWith('demo-'))}));const data=lists.get(key);if(data.loading)return empty('Loading whole-student reports','');if(data.error)return '<div class="error">'+esc(data.error)+'</div>';return `<div class="filters report-student-filters"><label class="field grow"><span>Find student</span><input id="report-student-search" value="${esc(filterText)}" placeholder="Name or form…"></label><label class="field"><span>Status</span><select id="report-student-status">${options([['all','All active reports'],['pending','Awaiting review'],['ready','Ready to issue'],['issued','Issued']],filterStatus)}</select></label></div><section class="panel report-entry-panel"><div class="panel-head"><h2>Whole-student reporting</h2><span class="badge">${data.students.length} students</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Student</th><th>Subject grades</th><th>Approval</th><th>Homeroom</th><th>Issued</th><th>Action</th></tr></thead><tbody id="whole-report-students">${studentRowsHtml(data.students,ctx)}</tbody></table></div></section>`;}
 function studentRowsHtml(rows,ctx){return rows.filter(r=>(!filterText||(r.student.name+' '+r.student.groupName).toLowerCase().includes(filterText.toLowerCase()))&&(filterStatus==='all'||filterStatus==='pending'&&(r.pending>0||r.homeroomStatus==='pending')||filterStatus==='ready'&&r.approved===r.total&&r.homeroomStatus==='approved'||filterStatus==='issued'&&r.issued>0)).map(r=>`<tr><td><strong>${esc(r.student.name)}</strong><small>${esc(r.student.groupName)}</small></td><td>${r.completed} / ${r.total} complete</td><td>${r.approved} approved · ${r.pending} submitted</td><td>${esc(r.homeroomStatus)}<small>${esc(r.homeroomTeacher)}</small></td><td>${r.issued?'v'+r.issued:'—'}</td><td><a class="btn small" href="#/cards?${new URLSearchParams({student:r.student.id,cycle:ctx.cycleId})}">Open report</a></td></tr>`).join('')||'<tr><td colspan="6">No reports match this view.</td></tr>';}
 function studentPage(ctx){const key=ctx.cycleId+'|'+ctx.studentId;load(bundles,key,'/student?'+new URLSearchParams({cycleId:ctx.cycleId,studentId:ctx.studentId}));const report=bundles.get(key);if(report.loading)return empty('Loading student report','');if(report.error)return '<div class="error">'+esc(report.error)+'</div>';if(!homeroomEditor||homeroomEditor.key!==key)homeroomEditor={key,...structuredClone(report.homeroom),dirty:false};if(homeroomEditor.dirty)ui.setDirty(true);const ownHomeroom=report.canWriteHomeroom&&report.homeroom.status==='draft',allSubmitted=report.rows.every(r=>['pending','approved'].includes(r.status))&&['pending','approved'].includes(report.homeroom.status);
 return `<div class="report-student-heading"><div><h1>${esc(report.student.name)} <small>${esc(report.student.groupName)}</small></h1><p>${esc(report.cycle.academicYear)} · ${esc(report.cycle.title)} · ${report.approvedRows}/${report.totalRows} subjects approved</p></div><div class="actions"><a class="btn small" href="#/cards?${new URLSearchParams({view:'students',cycle:ctx.cycleId})}">Reports</a><a class="btn small" href="#/student?id=${report.student.id}&tab=grades">Assessment tracking</a>${button('Draft PDF','report-download','','small')}${report.issueHistory.length>1?`<select id="issued-report-version" aria-label="Issued report version">${options(report.issueHistory.map(issue=>[String(issue.version),'Issued v'+issue.version]),String(report.latestIssue.version))}</select>`:''}${report.latestIssue?button(report.issueHistory.length>1?'Download issued PDF':'Issued PDF v'+report.latestIssue.version,'report-download','data-issued="true"','primary small'):''}</div></div><div id="page-error" class="error" role="alert"></div>${report.canReview?`<div class="report-review-controls">${button('Approve all submitted','report-approve-all',allSubmitted?'':'disabled','small')}${button(report.latestIssue?'Issue revised report':'Issue report','report-issue',report.readyToIssue?'':'disabled','primary small')}<span>${report.readyToIssue?'All required sections are approved.':'Every subject and the homeroom comment must be approved before issue.'}</span></div>`:''}<div class="report-preview"><div class="report-paper-header"><div><img src="assets/wist-report-logo.png" alt="WIST" width="1312" height="281"><p>${esc(report.brand.name)}<br>${esc(report.brand.address)}<br>${esc(report.brand.website)}</p></div><div><div class="report-pupil-banner"><strong>${esc(report.student.name.toUpperCase())}</strong><span>${esc(report.student.yearLabel)} · ${esc(report.student.form)}</span></div><h2>${esc(report.cycle.academicYear+' '+report.cycle.title.toUpperCase())}</h2><span class="badge ${report.latestIssue?'approved':'draft'}">${report.latestIssue?'Issued version '+report.latestIssue.version+' available':'Draft preview · not issued'}</span></div></div><section class="report-homeroom-section"><div class="section-label"><h3>Homeroom comments</h3><span class="badge ${report.homeroom.status}">${esc(report.homeroom.status)}</span></div><p class="muted">Form tutor: ${esc(report.homeroom.teacher)}</p>${ownHomeroom?`<textarea id="homeroom-report-comment" rows="5" maxlength="8000" aria-label="Homeroom report comment">${esc(homeroomEditor.comment)}</textarea><div class="report-homeroom-actions">${button('Save homeroom draft','report-save-homeroom','','small')}${button('Submit homeroom','report-submit-homeroom','','primary small')}</div>`:`<div class="report-comment-preview">${esc(report.homeroom.comment||'Homeroom comment not yet completed.').replaceAll('\n','<br>')}</div>`}${report.homeroom.reviewNote?`<p class="report-return-note">Returned: ${esc(report.homeroom.reviewNote)}</p>`:''}${report.canReview?reviewButtons(report.homeroom,'homeroom'):''}</section><section class="report-attendance-section"><h3>Attendance · ${esc(report.cycle.term)}</h3><div><span>Absent dates</span><strong>${report.attendance.absentDays===null?'Not recorded':report.attendance.absentDays}</strong></div><p>${esc(report.attendance.note)}</p></section><section class="report-subject-section"><div class="table-wrap"><table class="data-table report-paper-table"><thead><tr><th>Classes / teacher</th><th>Effort</th><th>Attainment</th><th>${esc(report.cycle.term)}</th><th>Workflow</th></tr></thead><tbody>${report.rows.map(r=>`<tr><td><strong>${esc(r.subject)}</strong><small>${esc(r.className)} · ${esc(r.teacher)}</small>${r.comment?`<p>${esc(r.comment).replaceAll('\n','<br>')}</p>`:''}</td><td>${esc(r.effort||'—')}</td><td>${esc(r.grade||'—')}</td><td class="report-term-column"></td><td><span class="badge ${r.status}">${esc(r.status)}</span>${report.canReview?reviewButtons(r,'subject'):''}${r.reviewNote?`<small class="report-return-note">${esc(r.reviewNote)}</small>`:''}</td></tr>`).join('')}</tbody></table></div></section><details class="report-grade-key"><summary>Key of our grades</summary><h3>Effort grades</h3>${report.effortKey.map(line=>'<p>'+esc(line)+'</p>').join('')}<h3>Attainment grades</h3>${report.attainmentKey.map(line=>'<p>'+esc(line)+'</p>').join('')}</details><div class="report-signoff"><strong>${esc(report.brand.signOffRole)}</strong><p>${report.latestIssue?'Issued on '+new Date(report.latestIssue.issuedAt).toLocaleDateString('en-GB',{timeZone:'Asia/Tashkent'}):'Review and issue pending.'}</p><p>Signature: __________________________</p><small>No signature image is attached to this prototype.</small></div></div>`;}
 function reviewButtons(row,kind){return ['pending','approved'].includes(row.status)?`<div class="report-inline-review">${row.status==='pending'?button('Approve','report-review',`data-id="${esc(row.id||row.studentId)}" data-kind="${kind}" data-decision="approve"`,'small'):''}${button('Return','report-review',`data-id="${esc(row.id||row.studentId)}" data-kind="${kind}" data-decision="return"`,'small')}</div>`:'';}
 async function saveRows(submit,onlyId){if(busy||!editor)return;const ctx=context(),rows=editor.rows.filter(r=>r.status==='draft'&&(!onlyId||r.id===onlyId)&&(!submit||r.grade&&r.effort));if(!rows.length){ui.error(submit?'Add attainment and effort for at least one row before submitting.':'There are no editable draft rows.');return;}await mutate('/save-rows',{cycleId:ctx.cycleId,classId:ctx.classId,submit,rows:rows.map(r=>({...r,expectedRevision:r.revision}))},submit?'Reports submitted for review.':'Report drafts saved.');}
 async function mutate(path,payload,message){if(busy)return;busy=true;const controls=[...document.querySelectorAll('#main input,#main select,#main textarea,#main button,#dialog[open] button')].map(el=>({el,disabled:el.disabled}));controls.forEach(({el})=>el.disabled=true);try{await api(path,{method:'POST',body:JSON.stringify(payload)});invalidate();ui.dialogDirty(false);if($('#dialog').open)ui.closeDialog(true);ui.render();ui.toast(message);}catch(error){ui.error(error.message);}finally{busy=false;controls.forEach(({el,disabled})=>{if(el.isConnected)el.disabled=disabled;});}}
 async function download(a){if(ui.isDirty()){ui.error('Save your changes before downloading the PDF.');return;}const ctx=context(),query={cycleId:ctx.cycleId,issued:String(a.dataset.issued==='true'),...($('#issued-report-version')?{version:$('#issued-report-version').value}:{}),...(a.dataset.scope==='class'?{classId:ctx.classId}:{studentId:ctx.studentId})};if(busy)return;busy=true;const old=a.textContent;a.disabled=true;a.textContent='Creating PDF…';try{const response=await fetch('/api/report-cards/pdf?'+new URLSearchParams(query),{credentials:'same-origin',cache:'no-store'});if(!response.ok){const data=await response.json();throw Error(data.error||'Could not create the report PDF.');}const name=response.headers.get('content-disposition')?.match(/filename="([^"]+)"/)?.[1]||'WIST-report.pdf';ui.download(name,await response.arrayBuffer(),'application/pdf');ui.toast('Report PDF downloaded.');}catch(error){ui.error(error.message);}finally{busy=false;if(a.isConnected){a.disabled=false;a.textContent=old;}}}
 function action(action,a){const ctx=context();if(action==='report-mode'){guard(()=>{editor=null;ui.setDirty(false);ui.navigate('/cards',{cycle:ctx.cycleId,...(ctx.classId?{class:ctx.classId}:{}),view:a.dataset.mode==='students'?'students':'entry'});});return true;}if(action==='report-discard'){ui.setDirty(false);editor=null;homeroomEditor=null;ui.closeDialog(true);const fn=pending;pending=null;fn?.();return true;}if(action==='report-save'||action==='report-submit'||action==='report-submit-row'){void saveRows(action!=='report-save',a.dataset.id);return true;}if(action==='report-feedback'){const row=editor?.rows.find(r=>r.id===a.dataset.id);ui.openDialog('Reviewer feedback','<p>'+esc(row?.reviewNote||'No feedback recorded.')+'</p>',button('Close','close'));return true;}if(action==='report-comment'){const row=editor?.rows.find(r=>r.id===a.dataset.id);if(!row)return true;ui.openDialog('Subject report comment',`<p class="muted">${esc(ui.student(row.studentId).name)} · ${esc(row.subject)}. Optional comments appear below this subject in the PDF.</p><textarea id="subject-report-comment" rows="5" maxlength="3000">${esc(row.comment)}</textarea>`,button('Cancel','close')+button('Apply comment','report-apply-comment',`data-id="${esc(row.id)}"`,'primary'));return true;}if(action==='report-apply-comment'){const row=editor.rows.find(r=>r.id===a.dataset.id);row.comment=$('#subject-report-comment').value;editor.dirty=true;ui.closeDialog(true);ui.render();return true;}if(action==='report-save-homeroom'||action==='report-submit-homeroom'){void mutate('/homeroom',{cycleId:ctx.cycleId,studentId:ctx.studentId,comment:homeroomEditor.comment,expectedRevision:homeroomEditor.revision,submit:action==='report-submit-homeroom'},action==='report-submit-homeroom'?'Homeroom report submitted.':'Homeroom draft saved.');return true;}if(action==='report-download'){void download(a);return true;}if(action==='report-review'){const report=bundles.get(ctx.cycleId+'|'+ctx.studentId),row=a.dataset.kind==='homeroom'?report.homeroom:report.rows.find(r=>r.id===a.dataset.id);const payload={cycleId:ctx.cycleId,studentId:ctx.studentId,kind:a.dataset.kind,id:row.id,expectedRevision:row.revision,decision:a.dataset.decision};if(a.dataset.decision==='return'){pending=()=>mutate('/review',{...payload,note:$('#return-report-note').value},'Report returned to its teacher.');ui.openDialog('Return for changes','<label class="field"><span>Reason for returning this report</span><textarea id="return-report-note" rows="4" maxlength="1000"></textarea></label>',button('Cancel','close')+button('Return report','report-confirm-return','','primary'));}else void mutate('/review',payload,'Report approved.');return true;}if(action==='report-confirm-return'){void pending?.();return true;}if(action==='report-approve-all'||action==='report-issue'){void mutate(action==='report-issue'?'/issue':'/approve-all',{cycleId:ctx.cycleId,studentId:ctx.studentId,expectedToken:bundles.get(ctx.cycleId+'|'+ctx.studentId).reviewToken},action==='report-issue'?'Report issued. Its saved PDF snapshot is now available.':'All submitted report sections approved.');return true;}return false;}
 function input(t){if(['subject-report-comment','return-report-note'].includes(t.id))ui.dialogDirty(true);if(t.dataset.reportField){const row=editor?.rows.find(r=>r.id===t.dataset.row);if(row){row[t.dataset.reportField]=t.value;editor.dirty=true;ui.setDirty(true);}}if(t.id==='homeroom-report-comment'){homeroomEditor.comment=t.value;homeroomEditor.dirty=true;ui.setDirty(true);}if(t.id==='report-student-search'){filterText=t.value;drawStudentList();}}
 function drawStudentList(){const ctx=context(),data=lists.get(ctx.cycleId+'|'+(ui.route().params.get('class')||''));if(data?.students&&$('#whole-report-students'))$('#whole-report-students').innerHTML=studentRowsHtml(data.students,ctx);}
 function change(t){input(t);if(t.id==='report-student-status'){filterStatus=t.value;drawStudentList();}if(['reporting-cycle','reporting-class','reporting-subject'].includes(t.id)){const ctx=context(),target={cycle:$('#reporting-cycle')?.value||ctx.cycleId,class:$('#reporting-class')?.value||ctx.classId,view:isReviewer()||ui.route().params.get('view')==='students'?'students':'entry',...(t.id==='reporting-subject'?{subject:t.value}:{})};guard(()=>{editor=null;homeroomEditor=null;ui.setDirty(false);ui.navigate('/cards',target);});if(t.id==='reporting-cycle')t.value=ctx.cycleId;if(t.id==='reporting-class')t.value=ctx.classId;}}
 async function migrate(root){if(isReviewer())return;await api('/import',{method:'POST',body:JSON.stringify({records:root.reports})});}
 return{page,action,input,change,migrate,api,isReviewer,invalidate};
}
